import { tags } from "typia";

/**
 * Aggregated share metrics for a specific payment method within a geographic
 * region.
 *
 * This object represents how frequently a given payment method is used and how
 * much revenue it contributes for the region over the aggregation window.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallGeographyStatisticsPaymentMethodShare = {
  /**
   * Stable code or identifier of the payment method (for example, "CARD",
   * "BANK_TRANSFER", "EWALLET"). Typically corresponds to a record in
   * shopping_mall_payment_methods or a similar reference table.
   */
  paymentMethodCode: string;

  /**
   * Human-readable name of the payment method for display purposes (e.g.,
   * "Credit Card", "Bank Transfer").
   */
  paymentMethodName: string;

  /**
   * Number of successful payments using this method in the region over the
   * aggregation window.
   */
  usageCount: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Fraction (0–1) of all successful payments in the region that used this
   * method. Typically, the sum of usageShare across all methods in a region
   * is close to 1.
   */
  usageShare: number & tags.Minimum<0> & tags.Maximum<1>;

  /**
   * Fraction (0–1) of total revenue in the region that was processed via this
   * payment method. This may differ from usageShare when average order values
   * vary by payment method.
   */
  revenueShare: number & tags.Minimum<0> & tags.Maximum<1>;
};
